function normalizeStartHammerHistoryEpochRequest(
  body: unknown,
): StartHammerHistoryEpochRequest {
  if (!isRecord(body))
    throw new HttpError(
      400,
      "history_epoch_request_invalid",
      "History epoch request must be an object.",
    );
  const allowed = new Set([
    "canonical_recording_id",
    "idempotency_key",
    "expected_revision_updated_at",
    "expected_history_path",
    "expected_predecessor",
    "epoch_path",
    "envelope",
  ]);
  if (
    Object.keys(body).some((key) => !allowed.has(key)) ||
    Object.keys(body).length !== allowed.size
  ) {
    throw new HttpError(
      400,
      "history_epoch_request_invalid",
      "History epoch request fields are invalid.",
    );
  }
  const predecessor = body.expected_predecessor;
  if (
    !isRecord(predecessor) ||
    Object.keys(predecessor).sort().join(",") !==
      "bytes,revision,sha256,updated_at"
  ) {
    throw new HttpError(
      400,
      "history_epoch_request_invalid",
      "Expected predecessor metadata is invalid.",
    );
  }
  const revision = predecessor.revision;
  const bytes = predecessor.bytes;
  const sha256 =
    typeof predecessor.sha256 === "string"
      ? predecessor.sha256.trim().toLowerCase()
      : "";
  if (
    !Number.isSafeInteger(revision) ||
    Number(revision) <= 0 ||
    !Number.isSafeInteger(bytes) ||
    Number(bytes) <= 0 ||
    !/^[0-9a-f]{64}$/.test(sha256)
  ) {
    throw new HttpError(
      400,
      "history_epoch_request_invalid",
      "Expected predecessor fingerprint is invalid.",
    );
  }
  const idempotencyKey = normalizeNonEmptyString(
    body.idempotency_key,
    "idempotency_key",
  );
  if (!/^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$/.test(idempotencyKey))
    throw new HttpError(
      400,
      "history_epoch_idempotency_key_invalid",
      "idempotency_key is not canonical.",
    );
  return {
    canonical_recording_id: normalizeUuid(
      body.canonical_recording_id,
      "canonical_recording_id",
    ),
    idempotency_key: idempotencyKey,
    expected_revision_updated_at: validateOpaqueCasTimestampToken(
      body.expected_revision_updated_at,
      "expected_revision_updated_at",
    ),
    expected_history_path: normalizeRelativePath(body.expected_history_path),
    expected_predecessor: {
      revision: Number(revision),
      updated_at: validateOpaqueCasTimestampToken(
        predecessor.updated_at,
        "expected_predecessor.updated_at",
      ),
      sha256,
      bytes: Number(bytes),
    },
    epoch_path: normalizeRelativePath(body.epoch_path),
    envelope: body.envelope as HammerHistoryEpochEnvelopeV1,
  };
}

function normalizeAdvanceHammerHistoryEpochHeadRequest(
  body: unknown,
): AdvanceHammerHistoryEpochHeadRequest {
  if (!isRecord(body))
    throw new HttpError(
      400,
      "history_epoch_head_request_invalid",
      "History epoch head request must be an object.",
    );
  const allowed = new Set([
    "canonical_recording_id",
    "idempotency_key",
    "expected_revision_updated_at",
    "expected_history_path",
    "expected_parent",
    "head_path",
    "envelope",
  ]);
  if (
    Object.keys(body).some((key) => !allowed.has(key)) ||
    Object.keys(body).length !== allowed.size
  )
    throw new HttpError(
      400,
      "history_epoch_head_request_invalid",
      "History epoch head request fields are invalid.",
    );
  const parent = body.expected_parent;
  if (
    !isRecord(parent) ||
    Object.keys(parent).sort().join(",") !==
      "head_id,revision,sequence,sha256,updated_at"
  )
    throw new HttpError(
      400,
      "history_epoch_head_request_invalid",
      "Expected parent metadata is invalid.",
    );
  const revision = Number(parent.revision);
  const sequence = Number(parent.sequence);
  const digest =
    typeof parent.sha256 === "string" ? parent.sha256.trim().toLowerCase() : "";
  if (
    !Number.isSafeInteger(revision) ||
    revision <= 0 ||
    !Number.isSafeInteger(sequence) ||
    sequence < 0 ||
    !/^[0-9a-f]{64}$/.test(digest)
  )
    throw new HttpError(
      400,
      "history_epoch_head_request_invalid",
      "Expected parent fingerprint is invalid.",
    );
  const idempotencyKey = normalizeNonEmptyString(
    body.idempotency_key,
    "idempotency_key",
  );
  if (!/^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$/.test(idempotencyKey))
    throw new HttpError(
      400,
      "history_epoch_head_idempotency_key_invalid",
      "idempotency_key is not canonical.",
    );
  return {
    canonical_recording_id: normalizeUuid(
      body.canonical_recording_id,
      "canonical_recording_id",
    ),
    idempotency_key: idempotencyKey,
    expected_revision_updated_at: validateOpaqueCasTimestampToken(
      body.expected_revision_updated_at,
      "expected_revision_updated_at",
    ),
    expected_history_path: normalizeRelativePath(body.expected_history_path),
    expected_parent: {
      head_id:
        parent.head_id === null
          ? null
          : normalizeUuid(parent.head_id, "expected_parent.head_id"),
      sha256: digest,
      revision,
      sequence,
      updated_at: validateOpaqueCasTimestampToken(
        parent.updated_at,
        "expected_parent.updated_at",
      ),
    },
    head_path: normalizeRelativePath(body.head_path),
    envelope: body.envelope as HammerHistoryEpochHeadEnvelopeV1,
  };
}

function normalizeCommitHammerHistoryAtomicRequest(
  body: unknown,
): CommitHammerHistoryAtomicRequest {
  if (!isRecord(body))
    throw new HttpError(
      400,
      "history_epoch_atomic_request_invalid",
      "Atomic history request must be an object.",
    );
  const keys = [
    "workspace_id",
    "workpiece_id",
    "canonical_recording_id",
    "recording_revision_id",
    "initiating_user_id",
    "idempotency_key",
    "operation_fingerprint",
    "expected_revision_updated_at",
    "expected_history_path",
    "parent",
    "component_authority",
    "component_changes",
    "head",
    "envelope",
    "history",
  ];
  if (Object.keys(body).sort().join("|") !== [...keys].sort().join("|"))
    throw new HttpError(
      400,
      "history_epoch_atomic_request_shape_invalid",
      "Atomic history request fields are not exact.",
    );
  if (!Array.isArray(body.component_changes) || !isRecord(body.head))
    throw new HttpError(
      400,
      "history_epoch_atomic_request_invalid",
      "Atomic history staged bytes are missing.",
    );
  const componentChanges = body.component_changes.map((value) => {
    if (!isRecord(value))
      throw new HttpError(
        400,
        "history_epoch_atomic_component_plan_invalid",
        "Component change must be an object.",
      );
    const changeKeys = [
      "component",
      "path",
      "expected",
      "next",
      "content_type",
      "serialized_bytes_base64",
    ];
    if (
      Object.keys(value).sort().join("|") !== changeKeys.sort().join("|") ||
      typeof value.serialized_bytes_base64 !== "string"
    )
      throw new HttpError(
        400,
        "history_epoch_atomic_component_plan_invalid",
        "Component change fields are not exact.",
      );
    const { serialized_bytes_base64, ...change } = value;
    return {
      ...change,
      serialized_bytes: decodeBase64(serialized_bytes_base64),
    };
  });
  const headKeys = [
    "head_id",
    "path",
    "sha256",
    "bytes",
    "registry_revision",
    "registry_updated_at",
    "content_type",
    "serialized_bytes_base64",
  ];
  if (
    Object.keys(body.head).sort().join("|") !== headKeys.sort().join("|") ||
    typeof body.head.serialized_bytes_base64 !== "string"
  )
    throw new HttpError(
      400,
      "history_epoch_atomic_head_invalid",
      "Head fields are not exact.",
    );
  const { serialized_bytes_base64: headBase64, ...head } = body.head;
  return {
    ...body,
    component_changes: componentChanges,
    head: { ...head, serialized_bytes: decodeBase64(headBase64) },
  } as unknown as CommitHammerHistoryAtomicRequest;
}

