function normalizeOpenHammerAuthorityRequest(
  body: Record<string, unknown>,
): OpenHammerAuthorityRequest {
  const operationKey = normalizeNonEmptyString(
    body.operation_key,
    "operation_key",
  );
  if (operationKey.length < 8 || operationKey.length > 200) {
    throw new HttpError(
      400,
      "invalid_payload",
      "operation_key must contain 8 to 200 characters",
    );
  }
  const transcriptPolicy =
    typeof body.transcript_policy === "undefined"
      ? "reuse_only"
      : normalizeNonEmptyString(body.transcript_policy, "transcript_policy");
  if (
    transcriptPolicy !== "reuse_only" &&
    transcriptPolicy !== "allow_ai_fallback"
  ) {
    throw new HttpError(
      400,
      "invalid_payload",
      "transcript_policy must be reuse_only or allow_ai_fallback",
    );
  }
  const revisionLabel =
    typeof body.revision_label === "undefined"
      ? undefined
      : body.revision_label === null
        ? null
        : normalizeNonEmptyString(body.revision_label, "revision_label");
  return {
    operation_key: operationKey,
    transcript_policy: transcriptPolicy,
    ...(typeof revisionLabel === "undefined"
      ? {}
      : { revision_label: revisionLabel }),
  };
}

function normalizeAdvanceHammerPreparationRequest(
  body: Record<string, unknown>,
): AdvanceHammerPreparationRequest {
  const expected = body.expected_state_version;
  if (!Number.isSafeInteger(expected) || (expected as number) < 1)
    throw new HttpError(
      400,
      "invalid_payload",
      "expected_state_version must be positive",
    );
  const action = normalizeNonEmptyString(
    body.action,
    "action",
  ) as AdvanceHammerPreparationRequest["action"];
  const allowed = new Set<AdvanceHammerPreparationRequest["action"]>([
    "await_transcript_choice",
    "authorize_ai",
    "begin_hydration",
    "mark_ready",
    "retry",
    "fail_recoverable",
    "block",
  ]);
  if (!allowed.has(action))
    throw new HttpError(400, "invalid_payload", "Unknown preparation action");
  const nullableUuid = (
    value: unknown,
    field: string,
  ): string | null | undefined =>
    typeof value === "undefined"
      ? undefined
      : value === null
        ? null
        : normalizeUuid(value, field);
  const nullableText = (
    value: unknown,
    field: string,
  ): string | null | undefined =>
    typeof value === "undefined"
      ? undefined
      : value === null
        ? null
        : normalizeNonEmptyString(value, field);
  return {
    expected_state_version: expected as number,
    action,
    transcript_job_id: nullableUuid(
      body.transcript_job_id,
      "transcript_job_id",
    ),
    transcript_artifact_path: nullableText(
      body.transcript_artifact_path,
      "transcript_artifact_path",
    ),
    failure_code: nullableText(body.failure_code, "failure_code"),
    failure_detail: nullableText(body.failure_detail, "failure_detail"),
  };
}

