  private async resolveRecordingSessionCreator(
    workspace: WorkspaceRow,
  ): Promise<string> {
    if (workspace.created_by) return workspace.created_by;

    const { data, error } = await this.supabase
      .schema("tongs")
      .from("workspace_members")
      .select("user_id,created_at")
      .eq("workspace_id", workspace.id)
      .order("created_at", { ascending: true })
      .limit(1);

    if (error) {
      throw new HttpError(
        502,
        "db_read_failed",
        "Failed to resolve recording session creator",
        {
          reason: error.message,
        },
      );
    }

    const fallback = data?.[0]?.user_id ?? null;
    if (!fallback) {
      throw new HttpError(
        409,
        "workspace_creator_missing",
        "Workspace has no creator/member to assign recording session created_by",
      );
    }

    return fallback;
  }

  private async resolveUserIdFromAccessToken(
    accessToken: string | null | undefined,
  ): Promise<string | null> {
    const token = accessToken?.trim();
    if (!token) return null;
    const { data, error } = await this.supabase.auth.getUser(token);
    if (error) {
      throw new HttpError(
        401,
        "invalid_user_token",
        "Unable to resolve user from provided access token",
        {
          reason: error.message,
        },
      );
    }
    return data.user?.id ?? null;
  }

  private async resolveWorkspaceRoleForUser(
    workspaceId: string,
    userId: string,
  ): Promise<WorkspaceRole | null> {
    const { data: workspaceRow, error: workspaceError } = await this.supabase
      .schema("tongs")
      .from("workspaces")
      .select("id,created_by")
      .eq("id", workspaceId)
      .maybeSingle();

    if (workspaceError) {
      throw new HttpError(
        502,
        "db_read_failed",
        "Failed to resolve workspace ownership",
        {
          reason: workspaceError.message,
        },
      );
    }

    if (!workspaceRow) {
      throw new HttpError(
        404,
        "workspace_not_found",
        `Workspace ${workspaceId} was not found`,
      );
    }

    if (workspaceRow.created_by && workspaceRow.created_by === userId) {
      return "owner";
    }

    const { data: membershipRow, error: membershipError } = await this.supabase
      .schema("tongs")
      .from("workspace_members")
      .select("role")
      .eq("workspace_id", workspaceId)
      .eq("user_id", userId)
      .maybeSingle();

    if (membershipError) {
      throw new HttpError(
        502,
        "db_read_failed",
        "Failed to resolve workspace membership role",
        {
          reason: membershipError.message,
        },
      );
    }

    return normalizeWorkspaceRole(membershipRow?.role ?? null);
  }

  private async assertWorkspaceRoleFromAccessToken(
    workspaceId: string,
    minRole: WorkspaceRole,
    userAccessToken: string | null | undefined,
  ): Promise<{ userId: string; role: WorkspaceRole }> {
    const userId = await this.resolveUserIdFromAccessToken(userAccessToken);
    if (!userId) {
      throw new HttpError(
        401,
        "missing_user_token_header",
        "Missing x-forge-user-authorization (or x-forge-user-token) header",
      );
    }

    const role = await this.resolveWorkspaceRoleForUser(workspaceId, userId);
    if (!role) {
      throw new HttpError(
        403,
        "workspace_access_denied",
        "You are not a member of this workspace",
      );
    }
    if (!workspaceRoleAtLeast(role, minRole)) {
      throw new HttpError(
        403,
        "insufficient_role",
        `This action requires ${minRole} role or higher`,
        {
          required: minRole,
          actual: role,
        },
      );
    }

    return { userId, role };
  }

  private async assertWorkspaceRole(
    workspaceId: string,
    minRole: WorkspaceRole,
    options?: { userAccessToken?: string | null; userId?: string | null },
  ): Promise<{ userId: string; role: WorkspaceRole }> {
    const userId = options?.userId?.trim() || null;
    if (!userId) {
      return this.assertWorkspaceRoleFromAccessToken(
        workspaceId,
        minRole,
        options?.userAccessToken,
      );
    }

    const role = await this.resolveWorkspaceRoleForUser(workspaceId, userId);
    if (!role) {
      throw new HttpError(
        403,
        "workspace_access_denied",
        "You are not a member of this workspace",
      );
    }
    if (!workspaceRoleAtLeast(role, minRole)) {
      throw new HttpError(
        403,
        "insufficient_role",
        `This action requires ${minRole} role or higher`,
        {
          required: minRole,
          actual: role,
        },
      );
    }
    return { userId, role };
  }

