  async transitionAnvilTakeCompletedV2(
    workpieceId: string,
    input: AnvilTakeCompletionV2Request,
  ): Promise<AnvilTakeTransitionResult> {
    const token = normalizeNonEmptyString(
      input.user_access_token,
      "user_access_token",
    );
    const cradle = await this.getCradleOrThrow(workpieceId);
    if (cradle.workspace_id !== input.workspace_id) {
      throw new HttpError(
        404,
        "workpiece_not_found",
        "Workpiece does not belong to the requested workspace.",
      );
    }
    const mediaPath = normalizeRelativePath(input.media_path);
    const fileResult = await this.supabase
      .schema("tongs")
      .from("workpiece_files")
      .select(
        "revision,hash_value,bytes,content_type,storage_bucket,storage_key",
      )
      .eq("workpiece_id", workpieceId)
      .eq("path", mediaPath)
      .maybeSingle();
    if (fileResult.error)
      throw new HttpError(
        502,
        "db_read_failed",
        "Failed to read recording metadata.",
        { reason: fileResult.error.message },
      );
    if (!fileResult.data)
      throw new HttpError(
        404,
        "media_not_found",
        "Recorded media metadata was not found.",
      );
    const stored = await downloadStorageObject(
      this.supabase,
      fileResult.data.storage_bucket,
      fileResult.data.storage_key,
    );
    if (!stored)
      throw new HttpError(
        409,
        "storage_verification_failed",
        "Recorded media could not be read back from storage.",
        { stage: "storage_readback" },
      );
    const storedHash = await sha256Hex(stored);
    if (
      stored.length !== input.expected_media_bytes ||
      storedHash !== input.expected_media_hash.toLowerCase()
    ) {
      throw new HttpError(
        409,
        "storage_verification_failed",
        "Recorded media readback did not match the completion request.",
        {
          stage: "storage_readback",
          expected_bytes: input.expected_media_bytes,
          actual_bytes: stored.length,
          expected_hash: input.expected_media_hash.toLowerCase(),
          actual_hash: storedHash,
        },
      );
    }
    if (!this.userClientFactory)
      throw new HttpError(
        503,
        "anvil_recording_authority_migration_required",
        "Anvil recording V2 authority is unavailable.",
      );
    const rpcClient = this.userClientFactory(token).schema(
      "tongs",
    ) as unknown as {
      rpc: (
        name: string,
        args: Record<string, unknown>,
      ) => Promise<{
        data: unknown;
        error: { code?: string; message: string } | null;
      }>;
    };
    const { data, error } = await rpcClient.rpc(
      "anvil_transition_take_completed_v2",
      {
        p_workspace_id: input.workspace_id,
        p_workpiece_id: workpieceId,
        p_capture_session_id: input.capture_session_id,
        p_recording_session_id: input.recording_session_id ?? null,
        p_script_path: input.script_path,
        p_expected_script_revision: input.expected_script_revision,
        p_expected_script_hash: input.expected_script_hash.toLowerCase(),
        p_media_path: mediaPath,
        p_expected_media_revision: input.expected_media_revision,
        p_expected_media_hash: input.expected_media_hash.toLowerCase(),
        p_expected_media_bytes: input.expected_media_bytes,
        p_expected_media_content_type:
          input.expected_media_content_type.toLowerCase(),
        p_storage_bucket: fileResult.data.storage_bucket,
        p_storage_key: fileResult.data.storage_key,
        p_idempotency_key: input.idempotency_key,
        p_completion_evidence: input.completion_evidence,
      },
    );
    if (error)
      throw new HttpError(
        error.code === "PGRST202" ? 503 : 502,
        "anvil_recording_transition_failed",
        "Anvil recording completion failed.",
        { reason: error.message },
      );
    if (!isRecord(data) || typeof data.outcome !== "string")
      throw new HttpError(
        502,
        "anvil_recording_transition_malformed",
        "Anvil recording completion returned malformed data.",
      );
    return data as AnvilTakeTransitionResult;
  }

