  async transitionAnvilTakeCompletedV3(
    workpieceId: string,
    input: AnvilTakeCompletionV3Request,
  ): Promise<AnvilTakeTransitionResult> {
    const token = normalizeNonEmptyString(
      input.user_access_token,
      "user_access_token",
    );
    const authorityResult = await (
      this.supabase.schema("tongs") as unknown as UntypedTongsSchemaClient
    )
      .from("recording_capture_authorities")
      .select("id,workspace_id,workpiece_id")
      .eq("id", input.capture_authority_id)
      .maybeSingle();
    if (authorityResult.error)
      throw new HttpError(
        502,
        "capture_authority_read_failed",
        "Anvil could not validate the capture authority.",
        { reason: authorityResult.error.message },
      );
    const authorityWorkpieceId = authorityResult.data
      ? readStringField(authorityResult.data, "workpiece_id")
      : null;
    const authorityWorkspaceId = authorityResult.data
      ? readStringField(authorityResult.data, "workspace_id")
      : null;
    if (
      !authorityWorkpieceId ||
      authorityWorkpieceId !== workpieceId ||
      !authorityWorkspaceId
    )
      throw new HttpError(
        409,
        "capture_authority_mismatch",
        "This recording is bound to a different episode.",
      );
    const auth = await this.assertWorkspaceRoleFromAccessToken(
      authorityWorkspaceId,
      "editor",
      token,
    );
    const mediaPath = normalizeRelativePath(input.media_path);
    const fileResult = await this.supabase
      .schema("tongs")
      .from("workpiece_files")
      .select(
        "revision,hash_value,bytes,content_type,storage_bucket,storage_key",
      )
      .eq("workpiece_id", workpieceId)
      .eq("path", mediaPath)
      .maybeSingle();
    if (fileResult.error || !fileResult.data)
      throw new HttpError(
        404,
        "media_not_found",
        "The uploaded recording could not be found for this episode.",
      );
    if (
      fileResult.data.revision !== input.expected_media_revision ||
      fileResult.data.hash_value.toLowerCase() !==
        input.expected_media_hash.toLowerCase() ||
      fileResult.data.bytes !== input.expected_media_bytes ||
      fileResult.data.content_type.toLowerCase() !==
        input.expected_media_content_type.toLowerCase()
    ) {
      throw new HttpError(
        409,
        "canonical_metadata_mismatch",
        "Canonical recording metadata did not match the completion request.",
      );
    }
    const stored = await downloadStorageObject(
      this.supabase,
      fileResult.data.storage_bucket,
      fileResult.data.storage_key,
    );
    const storedHash = stored ? await sha256Hex(stored) : null;
    if (
      !stored ||
      stored.length !== input.expected_media_bytes ||
      storedHash !== input.expected_media_hash.toLowerCase()
    ) {
      throw new HttpError(
        409,
        "canonical_storage_readback_mismatch",
        "The canonical storage object did not match its registered file revision.",
      );
    }
    const expectedKind = input.expected_media_content_type
      .toLowerCase()
      .startsWith("video/")
      ? "video"
      : "audio";
    let inspected: VerifiedBrollMedia;
    try {
      inspected = await this.brollAcquisitionRuntime.inspectMedia(
        stored,
        expectedKind,
      );
    } catch (error) {
      throw new HttpError(
        422,
        "canonical_media_probe_failed",
        "The canonical recording is not decodable media with the required streams.",
        {
          reason: error instanceof Error ? error.message : String(error),
        },
      );
    }
    if (
      (inspected.durationMs ?? 0) <= 0 ||
      inspected.hasAudioStream !== true ||
      (expectedKind === "video" && inspected.hasVideoStream !== true)
    ) {
      throw new HttpError(
        422,
        "canonical_media_streams_invalid",
        "The canonical recording is missing a required decodable media stream.",
      );
    }
    const expectedMediaType = input.expected_media_content_type
      .trim()
      .toLowerCase()
      .split(";", 1)[0]
      ?.trim();
    const inspectedMediaType = inspected.mimeType
      .trim()
      .toLowerCase()
      .split(";", 1)[0]
      ?.trim();
    if (!expectedMediaType || inspectedMediaType !== expectedMediaType) {
      throw new HttpError(
        409,
        "canonical_content_type_mismatch",
        "The canonical media signature did not match its registered content type.",
      );
    }
    const rpcClient = this.supabase.schema("tongs") as unknown as {
      rpc: (
        name: string,
        args: Record<string, unknown>,
      ) => Promise<{
        data: unknown;
        error: { code?: string; message: string } | null;
      }>;
    };
    const { data, error } = await rpcClient.rpc(
      "recording_transition_take_completed_verified",
      {
        p_recording_capture_authority_id: input.capture_authority_id,
        p_media_path: mediaPath,
        p_expected_media_revision: input.expected_media_revision,
        p_expected_media_hash: input.expected_media_hash.toLowerCase(),
        p_expected_media_bytes: input.expected_media_bytes,
        p_expected_media_content_type:
          input.expected_media_content_type.toLowerCase(),
        p_storage_bucket: fileResult.data.storage_bucket,
        p_storage_key: fileResult.data.storage_key,
        p_duration_ms: inspected.durationMs,
        p_has_audio_stream: inspected.hasAudioStream,
        p_has_video_stream: inspected.hasVideoStream === true,
        p_probe_implementation: "ffprobe:tongs-runtime",
        p_idempotency_key: input.idempotency_key,
        p_completion_evidence: input.completion_evidence,
        p_completed_by: auth.userId,
      },
    );
    if (error)
      throw new HttpError(
        error.code === "PGRST202" ? 503 : 502,
        "anvil_recording_transition_failed",
        "Anvil recording completion failed.",
        { reason: error.message },
      );
    if (!isRecord(data) || typeof data.outcome !== "string")
      throw new HttpError(
        502,
        "anvil_recording_transition_malformed",
        "Anvil recording completion returned malformed data.",
      );
    return data as AnvilTakeTransitionResult;
  }

