  async completePublicationStub(
    workpieceId: string,
    workspaceId: string,
    operationId: string,
    attemptId: string,
    options?: { userAccessToken?: string | null },
  ): Promise<Record<string, Json>> {
    const current = await this.readPublicationOperation(
      workpieceId,
      workspaceId,
      operationId,
      options,
    );
    const attempts = (
      Array.isArray(current.attempts) ? current.attempts.filter(isRecord) : []
    ) as Record<string, Json>[];
    const attempt = attempts.find(
      (row) =>
        row.id === attemptId && row.publication_operation_id === operationId,
    );
    if (!attempt || attempt.state !== "reserved")
      throw new HttpError(
        409,
        "publication_attempt_conflict",
        "The reserved publication attempt is unavailable.",
      );
    const authority = this.supabase.schema("tongs") as unknown as {
      rpc: (
        name: string,
        args: Record<string, unknown>,
      ) => Promise<UntypedPostgrestResult>;
    };
    const preparing = await authority.rpc(
      "record_publication_attempt_transition",
      {
        p_attempt_id: attemptId,
        p_expected_state: "reserved",
        p_new_state: "preparing_execution",
        p_side_effect_possible: false,
        p_adapter_id: "forge.stub",
        p_adapter_version: "s5-3b",
        p_failure_detail_json: null,
        p_normalized_provider_evidence: {},
      },
    );
    if (preparing.error)
      throw new HttpError(
        502,
        "publication_stub_failed",
        "Tongs could not prepare the stub attempt.",
      );
    const completed = await authority.rpc(
      "record_publication_attempt_transition",
      {
        p_attempt_id: attemptId,
        p_expected_state: "preparing_execution",
        p_new_state: "blocked",
        p_side_effect_possible: false,
        p_adapter_id: "forge.stub",
        p_adapter_version: "s5-3b",
        p_failure_code: "provider_execution_not_implemented",
        p_failure_detail_json: { external_side_effect_possible: false },
        p_normalized_provider_evidence: {
          stub: true,
          external_side_effect: false,
        },
      },
    );
    if (completed.error || !isRecord(completed.data))
      throw new HttpError(
        502,
        "publication_stub_failed",
        "Tongs could not persist the stub receipt.",
      );
    return completed.data as Record<string, Json>;
  }

  private async commitCanonicalQuenchDecision(
    workpieceId: string,
    input: CommitQuenchDecisionRequest,
    options?: { userAccessToken?: string | null },
  ): Promise<Record<string, Json>> {
    await this.assertWorkspaceRoleFromAccessToken(
      input.workspace_id,
      "editor",
      options?.userAccessToken,
    );
    const projection = await this.getQuenchCanonicalReleaseProjection(
      workpieceId,
      input.workspace_id,
      options,
    );
    if (projection.hammer.manifest_snapshot_id !== input.manifest_snapshot_id)
      throw new HttpError(
        409,
        "quench_review_manifest_advanced",
        "A newer Hammer package exists. Review it explicitly before changing release decisions.",
      );
    const set = projection.thumbnails.candidate_set;
    const scope = projection.destination_capabilities.find(
      (row) => row.id === input.destination_scope_id,
    );
    if (!set || !scope)
      throw new HttpError(
        409,
        "release_authority_unavailable",
        "The canonical candidate set or destination is unavailable.",
      );
    const capability = isRecord(scope.current_capability)
      ? scope.current_capability
      : {};
    const capabilityFlags = isRecord(capability.capabilities_json)
      ? capability.capabilities_json
      : {};
    if (
      input.intent_state === "experiment_planned" &&
      (capabilityFlags.supports_experiment_intent !== true ||
        capabilityFlags.supports_thumbnail_selection !== true)
    )
      throw new HttpError(
        409,
        "experiment_unsupported",
        "This destination does not support candidate experiment intent.",
      );
    if (
      input.intent_state === "selected" &&
      capabilityFlags.supports_thumbnail_selection !== true
    )
      throw new HttpError(
        409,
        "thumbnail_selection_unsupported",
        "This destination does not support thumbnail selection.",
      );
    for (const assignment of input.assignments) {
      const candidate = projection.thumbnails.candidates.find(
        (row) => row.id === assignment.candidate_revision_id,
      );
      if (
        !candidate ||
        candidate.authority_verified !== true ||
        !(["current", "approved_historical_brand"] as unknown[]).includes(
          candidate.eligibility_state,
        )
      )
        throw new HttpError(
          409,
          "candidate_ineligible",
          "An assigned candidate is not currently selectable through Tongs.",
        );
    }
    const params = {
      p_workspace_id: input.workspace_id,
      p_workpiece_id: workpieceId,
      p_destination_scope_id: input.destination_scope_id,
      p_expected_decision_id: input.expected_decision_id ?? null,
      p_expected_revision: input.expected_revision,
      p_decision_kind: input.decision_kind,
      p_intent_state: input.intent_state,
      p_manifest_snapshot_id: projection.hammer.manifest_snapshot_id,
      p_metadata_revision: projection.metadata.revision,
      p_metadata_hash: projection.metadata.content_hash,
      p_candidate_set_id: String(set.id),
      p_active_binding_id: projection.thumbnails.active_binding_id,
      p_capability_revision_id: String(scope.current_capability_revision_id),
      p_assignments: input.assignments,
      p_operation_id: input.operation_id,
      p_operation_fingerprint: "0".repeat(64),
    };
    const client = this.thumbnailAuthorityClient(options?.userAccessToken);
    const raw = this.supabase.schema(
      "tongs",
    ) as unknown as UntypedTongsSchemaClient;
    const receipt = await raw
      .from("quench_release_operation_receipts")
      .select(
        "operation_fingerprint,workspace_id,workpiece_id,destination_scope_id",
      )
      .eq("operation_id", input.operation_id)
      .maybeSingle();
    let fingerprint =
      isRecord(receipt.data) &&
      receipt.data.workspace_id === input.workspace_id &&
      receipt.data.workpiece_id === workpieceId &&
      receipt.data.destination_scope_id === input.destination_scope_id
        ? readStringField(receipt.data, "operation_fingerprint")
        : null;
    if (!fingerprint) {
      const discovery = await client.rpc("commit_quench_release_decision", {
        ...params,
        p_operation_id: `${input.operation_id}:fingerprint-probe`,
      });
      if (discovery.error)
        throw new HttpError(
          502,
          "release_decision_failed",
          "Tongs could not commit the release decision.",
          { reason: discovery.error.message },
        );
      if (!isRecord(discovery.data))
        throw new HttpError(
          502,
          "release_decision_invalid",
          "Tongs returned an invalid release decision result.",
        );
      fingerprint = readStringField(discovery.data, "canonical_fingerprint");
      if (!fingerprint) return discovery.data as Record<string, Json>;
    }
    const committed = await client.rpc("commit_quench_release_decision", {
      ...params,
      p_operation_fingerprint: fingerprint,
    });
    if (committed.error || !isRecord(committed.data))
      throw new HttpError(
        502,
        "release_decision_failed",
        "Tongs could not commit the release decision.",
        { reason: committed.error?.message },
      );
    return committed.data as Record<string, Json>;
  }

  async commitQuenchSingleCandidate(
    workpieceId: string,
    input: CommitQuenchSingleCandidateRequest,
    options?: { userAccessToken?: string | null },
  ) {
    return this.commitCanonicalQuenchDecision(
      workpieceId,
      {
        ...input,
        decision_kind: "single_candidate",
        intent_state: "selected",
        assignments: [
          {
            candidate_revision_id: input.candidate_revision_id,
            assignment_role: "selected",
            assignment_ordinal: 1,
            allocation_basis_points: null,
          },
        ],
      },
      options,
    );
  }
